def company():
    return deepcopy(COMPANY)

def sms_reference():
    return dict(id='ATM-SMS-001', category='Company SMS', filename='Aster Tide Marine fictional SMS',
        scope='Fictional company procedure manual based on the supplied ISM copy. Demonstration only; not certified or operationally approved.',
        status='Fictional authored text', pages=None, sha256='Not an imported source file', edition='Revision 0.2 — demonstration draft',
        imported=COMPANY['date'], validity='Fictional scenario policy; no real operational approval',
        chunks=[dict(id=f'ATM-SMS-{number}', locator=f'Company SMS section {number}: {title}',
                     text=f'{title}\nISM basis: {basis}\n{text}') for number,title,basis,text in SECTIONS])

def markdown():
    opening = ['# Aster Tide Marine Safety Management System', '',
        '**Fictional company and vessel • Demonstration draft • ATM-SMS-001 • Revision 0.2 • 31 October 2026**', '',
        'This manual defines the fictional company context for Fleet Ops AI. It uses the user-supplied ISM Code as its organizing basis and adds explicitly fictional company procedures. It is not a certified SMS, a compliance assessment or a shipboard operating instruction.', '',
        f"Company: {COMPANY['name']}  \nVessel: {COMPANY['vessel']} — {COMPANY['vessel_type']}  \nFlag: {COMPANY['flag']}", '',
        'The three AI roles support this company’s human shore organization. The Master retains overriding safety authority. The human DPA retains a direct route to highest management. Human review is required; agent text is a draft.', '']
    for number,title,basis,text in SECTIONS:
        opening += [f'## ATM-SMS-{number} {title}', '', f'ISM source mapping: {basis}.', '', text, '']
    return '\n'.join(opening)

def html_page():
    sections = ''.join(f'<section id="sms-{number}"><h2>ATM-SMS-{number} {escape(title)}</h2><p class="basis">ISM source mapping: {escape(basis)}</p><p>{escape(text)}</p></section>' for number,title,basis,text in SECTIONS)
    return ('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
        '<title>Aster Tide Marine SMS</title><style>body{font:17px/1.7 Segoe UI,system-ui,sans-serif;background:#091321;color:#dce8f4;max-width:1000px;margin:auto;padding:28px}a{color:#75d8ce}h1,h2{line-height:1.3}h2{font-size:21px;color:#75d8ce}section{padding:20px 0;border-top:1px solid #30445b}.basis{font-size:14px;color:#9fb4cb}.notice{padding:16px;background:#2d2a25;border-left:4px solid #edbb62}@media print{body{background:white;color:black}h2,a{color:black}}</style></head><body>'
        '<nav><a href="/">← Return to Fleet Ops AI</a> · <a href="/sms-download.md">Download Markdown</a></nav>'
        '<h1>Aster Tide Marine Safety Management System</h1>'
        f'<p>ATM-SMS-001 · Revision {escape(COMPANY["revision"])} · 31 October 2026</p>'
        '<p class="notice">Fictional company and vessel. Demonstration draft, not a certified SMS or shipboard operating instruction. The three AI agents support human company personnel; the Master retains overriding safety authority.</p>'
        '<p>Vessel: MT Aster Horizon. Oil tanker with a MITSUI-MAN B&amp;W 7S50MC-C main engine — fictional installation.</p>'
        + sections + '</body></html>')
